/**
 * Your adapter. This file is yours: replace the stub.
 *
 * `createInventoryClient(service, options)` must return `{ getItem(id), createItem(input) }`.
 * `options.now()` is the service's clock and `options.sleep(ms)` is how you wait. See specification.md for the
 * contract, and conformance/cases.mjs for exactly what is checked.
 */

function serviceError(status, body) {
	const code = body?.error?.code ?? "unknown_error";
	const err = new Error(body?.error?.message ?? `request failed with status ${status}`);
	err.name = "ServiceError";
	err.status = status;
	err.code = code;
	return err;
}

export function createInventoryClient(service, options) {
	const now = options?.now;
	const cache = new Map();
	let token = null;
	let expiresAtMs = 0;
	let idempotencyCounter = 0;

	async function fetchToken() {
		const { body } = await service.request("POST", "/auth/token");
		token = body.token;
		expiresAtMs = body.expiresAtMs;
	}

	async function authorizedRequest(method, path, { headers, body } = {}) {
		if (token === null || now() >= expiresAtMs) {
			await fetchToken();
		}
		const attempt = () =>
			service.request(method, path, { headers: { ...headers, authorization: `Bearer ${token}` }, body });

		let res = await attempt();
		if (res.status === 401) {
			await fetchToken();
			res = await attempt();
			if (res.status === 401) throw serviceError(res.status, res.body);
			return res;
		}
		if (res.status >= 500 && res.status <= 599) {
			res = await attempt();
		}
		return res;
	}

	async function getItem(id) {
		const cached = cache.get(id);
		const headers = cached ? { "if-none-match": cached.etag } : {};
		const res = await authorizedRequest("GET", `/items/${id}`, { headers });
		if (res.status === 304) return cached.item;
		if (res.status === 200) {
			cache.set(id, { etag: res.etag, item: res.body });
			return res.body;
		}
		if (res.status === 404) return null;
		throw serviceError(res.status, res.body);
	}

	async function createItem(input) {
		idempotencyCounter += 1;
		const key = `key-${idempotencyCounter}`;
		const res = await authorizedRequest("POST", "/items", { headers: { "idempotency-key": key }, body: input });
		if (res.status === 201 || res.status === 200) return res.body;
		if (res.status === 422) {
			const err = new Error(res.body?.error?.message ?? "validation failed");
			err.name = "ValidationError";
			err.fields = res.body?.error?.fields ?? [];
			throw err;
		}
		throw serviceError(res.status, res.body);
	}

	return { getItem, createItem };
}
